command:
cd /app && cat <<'EOF' > summary.py
import csv, os, re
from datetime import date, timedelta

REF = date(2025, 8, 12)
SEVERITIES = ["ERROR", "WARNING", "INFO"]
LOGDIR = "/app/logs"

ranges = {
    "today": REF,
    "last_7_days": REF - timedelta(days=6),
    "last_30_days": REF - timedelta(days=29),
    "month_to_date": REF.replace(day=1),
}
counts = {p: {s: 0 for s in SEVERITIES} for p in list(ranges) + ["total"]}

fname_re = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")
sev_re = re.compile(r"\[(ERROR|WARNING|INFO)\]")

for name in sorted(os.listdir(LOGDIR)):
    m = fname_re.match(name)
    if not m:
        continue
    d = date.fromisoformat(m.group(1))
    if d > REF:
        continue
    with open(os.path.join(LOGDIR, name), encoding="utf-8", errors="replace") as f:
        for line in f:
            sm = sev_re.search(line)
            if not sm:
                continue
            sev = sm.group(1)
            counts["total"][sev] += 1
            for period, start in ranges.items():
                if start <= d <= REF:
                    counts[period][sev] += 1

with open("/app/summary.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["period", "severity", "count"])
    for period in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for sev in SEVERITIES:
            w.writerow([period, sev, counts[period][sev]])
EOF
python3 summary.py && echo "--- summary.csv ---" && cat summary.csv
